              "text": "Термин «информационное общество» стал широко использоваться в работах японских учёных Юдзиро Хаяси и Ёнэдзи Масуды в 1960–1970-е гг. В различных теоретических концепциях информационное общество рассматривается либо как одна из разновидностей постиндустриального общества, либо как качественно новая ступень в общественном развитии. Его возникновение стало реальностью и нашло отражение в международных документах."
