              "type": "p",
              "text": "Гражданское право — отрасль права, представляющая совокупность правовых норм, регулирующих отношения между гражданами и организациями (юридическими лицами), направленные на удовлетворение их собственных нужд, потребностей и интересов. Это основополагающая отрасль частного права: садясь в автобус, мы вступаем в договор перевозки, принимая подарок — в отношения с дарителем. Основной источник регулирования — Гражданский кодекс Республики Беларусь (ГК); нормы гражданского права в других законах должны ему соответствовать."
