              "text": "Административное право — это отрасль права, представляющая совокупность правовых норм, регулирующих общественные отношения, которые возникают в процессе организации и осуществления государственного управления. Не случайно его часто называют управленческим правом: в переводе с латинского administratio обозначает «управление». Особенность этих отношений в том, что их обязательной стороной выступают органы государственного управления или их представители — прежде всего органы исполнительной власти (Совет Министров Республики Беларусь, исполкомы, местные администрации). Нормы отрасли обеспечивают слаженную работу всех государственных органов и организаций, регулируют управление экономикой, промышленностью, сельским хозяйством, транспортом и связью, образованием, здравоохранением, обороной, финансами."
