              "type": "p",
              "text": "Одним из перспективных направлений экономического роста является агроэкотуризм — экологический вид туризма, использующий природные, культурно-исторические и иные ресурсы сельской местности для создания комплексного туристического продукта. В 2016 и 2018 гг. Беларусь была признана лучшей страной для агротуризма в конкурсе журнала National Geographic Traveler. В стране насчитывается более двух тысяч агроусадеб; агроэкотуризм поддерживает молодёжь, которая видит в усадьбах пример успешного семейного бизнеса."
